create or replace function platform.drill_def__ai_usage()
returns jsonb
language sql
immutable
set search_path to 'pg_catalog'
as $function$
  select $drill${"key":"ai_usage","fact":"ai_usage_hourly","mode":"definer","grain":"one row per hour for each organization, person, agent, provider, model, app, feature, origin, manual or automated, and source","label":"AI usage","lanes":["platform","organization","mine"],"paths":[{"key":"who","label":"Who","levels":["organization","person"]},{"key":"what","label":"What","levels":["provider","model"]},{"key":"where","label":"Where","levels":["app","feature","agent"]},{"key":"when","label":"When","levels":["at:month","at:week","at:day","at:hour"]}],"detail":{"open":"/administration/billing/spend","columns":["bucket","organization_id","person_id","provider","model","feature","cost","tokens_in","tokens_out"]},"default":{"by":["person"],"path":"who","show":["cost","requests","tokens_in","tokens_out"],"sort":{"key":"cost","direction":"desc"},"window":{"key":"at","preset":"30d"}},"records":{"fact":"ai_usage_executions","labels":{"model":"Request's top model","provider":"Request's top model's provider","requests":"Request (counted on its first call)","tokens_in":"Request input tokens (on its first call)","call_model":"Model this call billed","created_at":"When","iterations":"Request iterations (on its first call)","request_id":"Request","tokens_out":"Request output tokens (on its first call)","execution_id":"Execution","tokens_cached":"Request cached tokens (on its first call)","unpriced_calls":"Request calls with no price (on its first call)","conversation_id":"Conversation","got_nothing_back":"Request got nothing back"},"columns":["created_at","execution_id","organization_id","person_id","agent_id","app","feature","origin","trigger","source","cost","call_model","model","provider","requests","tokens_in","tokens_cached","tokens_out","unpriced_calls","iterations","got_nothing_back","request_id","conversation_id"]},"measures":[{"of":"cost","op":"sum","key":"cost","unit":"usd","label":"Cost","additive":true},{"of":"calls","op":"sum","key":"calls","unit":"count","label":"Calls","additive":true},{"of":"requests","op":"sum","key":"requests","unit":"count","label":"Requests","additive":true},{"of":"tokens_in","op":"sum","key":"tokens_in","unit":"tokens","label":"Input tokens","additive":true},{"of":"tokens_out","op":"sum","key":"tokens_out","unit":"tokens","label":"Output tokens","additive":true},{"of":"tokens_cached","op":"sum","key":"tokens_cached","unit":"tokens","label":"Cached tokens","additive":true},{"of":"unpriced_calls","op":"sum","key":"unpriced_calls","unit":"count","label":"Calls with no price","additive":true},{"of":"person_id","op":"count_distinct","key":"people","unit":"count","label":"People","additive":false}],"dimensions":[{"key":"organization","from":"organization_id","kind":"relation","label":"Organization","relation":{"token":"organization"}},{"key":"person","from":"person_id","kind":"relation","label":"Person","relation":{"token":"user","person":true}},{"key":"provider","from":"provider","kind":"choice","label":"Provider","cardinality":"low"},{"key":"model","from":"model","kind":"choice","label":"Model","cardinality":"medium"},{"key":"app","from":"app","kind":"choice","label":"App","cardinality":"low"},{"key":"feature","from":"feature","kind":"choice","label":"Feature","cardinality":"medium"},{"key":"agent","from":"agent_id","kind":"relation","label":"Agent","relation":{"token":"agent"},"cardinality":"medium"},{"key":"origin","from":"origin","kind":"choice","label":"Origin","cardinality":"low"},{"key":"trigger","from":"trigger","kind":"choice","label":"Manual or automated","cardinality":"low"},{"key":"source","from":"source","kind":"choice","label":"Source","cardinality":"low"},{"key":"at","from":"bucket","kind":"time","label":"When","grains":["year","quarter","month","week","day","hour"]}],"lane_rules":{"mine":{"column":"person_id"},"platform":{"rule":"super_admin"},"organization":{"rule":"admin","column":"organization_id"}},"stale_after_knob":"drill.usage.stale_after_minutes"}$drill$::jsonb;
$function$;

